package org.jsoup.parser;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Tests {@link TokenQueue#escapeCssIdentifier(String)}: given a raw identifier, it should produce the
 * CSS-serialized form where special characters are escaped as defined by the CSS Object Model.
 *
 * <p>Non-ASCII and control-character values are written with {@code \\uXXXX} escapes so the exact code
 * points are unambiguous in source.</p>
 */
public class TokenQueueTest_escapeCssIdentifier {

    /**
     * Cases adapted from the Web Platform Tests for {@code CSS.escape}.
     * See https://github.com/web-platform-tests/wpt/blob/328fa1c67bf5dfa6f24571d4c41dd10224b6d247/css/cssom/escape.html
     *
     * @return pairs of (expected escaped output, raw input identifier)
     */
    private static Stream<Arguments> webPlatformTestCases() {
        return Stream.of(
            // Empty input is returned unchanged
            Arguments.of("", ""),

            // Null bytes become the replacement character (U+FFFD)
            Arguments.of("�", "�"),
            Arguments.of("a�", "a�"),
            Arguments.of("�b", "�b"),
            Arguments.of("a�b", "a�b"),

            // Existing replacement characters are preserved
            Arguments.of("�", "�"),
            Arguments.of("a�", "a�"),
            Arguments.of("�b", "�b"),
            Arguments.of("a�b", "a�b"),

            // A leading digit is escaped as a code point
            Arguments.of("\\30 a", "0a"),
            Arguments.of("\\31 a", "1a"),
            Arguments.of("\\32 a", "2a"),
            Arguments.of("\\33 a", "3a"),
            Arguments.of("\\34 a", "4a"),
            Arguments.of("\\35 a", "5a"),
            Arguments.of("\\36 a", "6a"),
            Arguments.of("\\37 a", "7a"),
            Arguments.of("\\38 a", "8a"),
            Arguments.of("\\39 a", "9a"),

            // A digit that is not the first character is left as-is
            Arguments.of("a0b", "a0b"),
            Arguments.of("a1b", "a1b"),
            Arguments.of("a2b", "a2b"),
            Arguments.of("a3b", "a3b"),
            Arguments.of("a4b", "a4b"),
            Arguments.of("a5b", "a5b"),
            Arguments.of("a6b", "a6b"),
            Arguments.of("a7b", "a7b"),
            Arguments.of("a8b", "a8b"),
            Arguments.of("a9b", "a9b"),

            // A digit directly after a leading dash is escaped as a code point
            Arguments.of("-\\30 a", "-0a"),
            Arguments.of("-\\31 a", "-1a"),
            Arguments.of("-\\32 a", "-2a"),
            Arguments.of("-\\33 a", "-3a"),
            Arguments.of("-\\34 a", "-4a"),
            Arguments.of("-\\35 a", "-5a"),
            Arguments.of("-\\36 a", "-6a"),
            Arguments.of("-\\37 a", "-7a"),
            Arguments.of("-\\38 a", "-8a"),
            Arguments.of("-\\39 a", "-9a"),

            // A leading double dash needs no escaping
            Arguments.of("--a", "--a"),

            // Control characters [U+0001..U+001F] are escaped as code points
            Arguments.of("\\1 \\2 \\1e \\1f ", ""),

            // Code points >= U+0080, plus '-' and '_', pass through unescaped
            Arguments.of("-_©", "-_©"),

            // U+007F is escaped as a code point; the C1 control range [U+0080..U+009F] passes through
            Arguments.of(
                "\\7f ",
                ""),
            Arguments.of(" ¡¢", " ¡¢"),
            Arguments.of("a0123456789b", "a0123456789b"),
            Arguments.of("abcdefghijklmnopqrstuvwxyz", "abcdefghijklmnopqrstuvwxyz"),
            Arguments.of("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "ABCDEFGHIJKLMNOPQRSTUVWXYZ"),

            // Backslashes get backslash-escaped
            Arguments.of("hello\\\\world", "hello\\world"),

            // Code points greater than U+0080 are preserved
            Arguments.of("helloሴworld", "helloሴworld"),

            // A single dash / punctuation is escaped
            Arguments.of("\\-", "-"),
            Arguments.of("\\ \\!xy", " !xy"),

            // Astral symbol (U+1D306 TETRAGRAM FOR CENTRE) is preserved
            Arguments.of("𝌆", "𝌆"),

            // Lone surrogates are preserved
            Arguments.of("\uDF06", "\uDF06"),
            Arguments.of("\uD834", "\uD834"));
    }

    /**
     * Additional jsoup-specific cases.
     *
     * @return pairs of (expected escaped output, raw input identifier)
     */
    private static Stream<Arguments> additionalTestCases() {
        return Stream.of(
            Arguments.of("one\\#two\\.three\\/four\\\\five", "one#two.three/four\\five"),
            Arguments.of("-a", "-a"),
            Arguments.of("--", "--"));
    }

    @ParameterizedTest(name = "escapeCssIdentifier(\"{1}\") -> \"{0}\"")
    @MethodSource("webPlatformTestCases")
    @MethodSource("additionalTestCases")
    public void escapesIdentifierToExpectedCssSerialization(String expected, String rawIdentifier) {
        assertEquals(expected, TokenQueue.escapeCssIdentifier(rawIdentifier));
    }
}
